// 1 when the bundled monospace face draws `cp` one cell wide, else 2.
export function codePointCells(cp) {
  let lo = 0;
  let hi = ONE_CELL_RUNS.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const run = ONE_CELL_RUNS[mid];
    if (cp < run[0]) hi = mid - 1;
    else if (cp > run[1]) lo = mid + 1;
    else return 1;
  }
  return 2;
}

// Cells of one character (a string holding a single code point).
export function charCells(ch) {
  return codePointCells(ch.codePointAt(0));
}

// Total cells of `text`, counted per code point.
export function textCells(text) {
  let cells = 0;
  for (const ch of String(text ?? "")) cells += charCells(ch);
  return cells;
}
